SELECT Имена_ОЭС.nameoes, Имена_областей.NAME AS oblast, [Расчёт средней цены топлива].NUMB1120, Имена_станций.NAME, Затраты_топливо_2021.cena_e, Затраты_топливо_2021.cena_Be, Затраты_топливо_2021.cena_Bt, [Расчёт средней цены топлива].avg_gaz_c, [Расчёт средней цены топлива].avg_ugol
FROM Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Имена_станций INNER JOIN ([Расчёт средней цены топлива] LEFT JOIN Затраты_топливо_2021 ON [Расчёт средней цены топлива].NUMB1120 = Затраты_топливо_2021.NUMB1120) ON Имена_станций.NUMB = [Расчёт средней цены топлива].NUMB1120) ON Имена_ОЭС.oes = Имена_станций.OES) ON Имена_областей.OBL = Имена_станций.OBL
ORDER BY Имена_станций.ordnumb;
